// S53 flag-off guard: drives a real collector on a FAKE clock through a fixed
// scenario that touches every pre-S53 collector method, then renders
// `activity.ndjson`, `results.json` and `summary.md` and compares them
// byte-for-byte against fixtures that were generated by the code as it stood
// BEFORE the heavy-load changes (S53). Every S53 addition (pump, wallet
// balances, L1 info tree, http windows, tx events, approve gas, claim
// pre-state) is optional and off by default, so a config that sets none of them
// must keep producing exactly these bytes.
//
// Regenerate deliberately (never to make a failing run pass) with
// `LOADTEST_UPDATE_GOLDEN=1 pnpm exec vitest run loadtest/metrics/flagOff.golden.test.ts`.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import type { LoadtestConfig } from '../config/schema';

import { buildTestDevnetConfig } from '../wallets/testHelpers';
import { createCollector, createMemoryActivitySink } from './collector';
import { buildResultsJson, renderSummaryMd } from './report';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// `results.json.golden`, not `.json`: lint-staged runs prettier over `*.json`, which would reformat the fixture.
const GOLDEN_FILES = {
  'activity.ndjson': 'activity.ndjson',
  'results.json': 'results.json.golden',
  'summary.md': 'summary.md'
} as const;

const GOLDEN_DIR = path.join(__dirname, '__fixtures__', 'flagOff');

const FAKE_TX = `0x${'ab'.repeat(32)}`;

const buildScenario = () => {
  let now = Date.UTC(2026, 9, 14, 12, 0, 0);
  const clock = { now: () => now };
  const advance = (ms: number): void => {
    now += ms;
  };
  const sink = createMemoryActivitySink();
  const collector = createCollector({ clock, activitySink: sink });

  collector.runStart({
    toolVersion: 'golden-tool',
    sdkVersion: 'golden-sdk',
    host: { cores: 4, totalMemMb: 8192, platform: 'linux' },
    rampUpSeconds: 10
  });
  collector.userReady('u0', 'headless');
  collector.userReady('u1', 'headless');

  for (let lap = 0; lap < 3; lap += 1) {
    advance(7_000);
    collector.tick('u0', 'headless');
    collector.hopState({
      userId: 'u0',
      mode: 'headless',
      hopId: `u0:a0:l${lap}:h0`,
      lapId: `u0:a0:l${lap}`,
      from: 'PLANNED',
      to: 'BRIDGE_BUILD',
      transition: 'T4'
    });
    collector.recordPhase({
      phase: 'bridge_submit',
      mode: 'headless',
      hopRoute: 'L1->L2A',
      assetKind: 'eth',
      durationMs: 400 + lap * 10
    });
    collector.recordPhase({
      phase: 'ready_to_claim',
      mode: 'headless',
      hopRoute: 'L1->L2A',
      assetKind: 'eth',
      durationMs: 30_000 + lap * 1_000
    });
    collector.recordPhase({
      phase: 'claim_receipt',
      mode: 'headless',
      hopRoute: 'L1->L2A',
      assetKind: 'eth',
      durationMs: 5_000,
      censored: lap === 2
    });
    collector.recordGateVisit({
      gate: 'claim-proof',
      durationMs: 31_000 + lap,
      timedOut: lap === 2
    });
    collector.recordHttpSample({
      userId: 'u0',
      mode: 'headless',
      endpointClass: 'tracker/activity',
      method: 'GET',
      status: lap === 1 ? 503 : 200,
      durationMs: 20 + lap,
      attempt: 0,
      origin: 'ui'
    });
    collector.recordHttpSample({
      userId: 'u0',
      mode: 'headless',
      endpointClass: 'rpc/l1rpc/eth_call',
      method: 'POST',
      status: 200,
      durationMs: 11,
      attempt: 0,
      origin: 'ui'
    });
    collector.recordHttpSample({
      userId: 'u0',
      mode: 'headless',
      endpointClass: 'bridge/claim-proof[1]',
      method: 'GET',
      status: 200,
      durationMs: 90,
      attempt: lap === 2 ? 1 : 0,
      origin: 'harness'
    });
    collector.recordHopCounter('claim_race_lost');
    collector.hopEnd({
      userId: 'u0',
      mode: 'headless',
      hopId: `u0:a0:l${lap}:h0`,
      lapId: `u0:a0:l${lap}`,
      hopRoute: 'L1->L2A',
      outcome: lap === 2 ? 'timeout_ready_to_claim' : 'hop_completed_manual'
    });
    collector.hopMeasurement({
      hopId: `u0:a0:l${lap}:h0`,
      lapId: `u0:a0:l${lap}`,
      userId: 'u0',
      mode: 'headless',
      hopRoute: 'L1->L2A',
      fromNetworkId: 0,
      toNetworkId: 1,
      assetKind: 'eth',
      assetIndex: 0,
      outcome: lap === 2 ? 'timeout_ready_to_claim' : 'hop_completed_manual',
      depositCount: lap,
      bridge: {
        txHash: FAKE_TX,
        blockNumber: '100',
        minedObservedAt: now,
        gas: { blockNumber: '100', gasUsed: '90000', effectiveGasPrice: '1000000' }
      },
      stages: null,
      readyObservedAt: now + 30_000,
      claim: {
        txHash: FAKE_TX,
        blockNumber: '120',
        sentAt: now + 31_000,
        minedObservedAt: now + 33_000,
        gas: { blockNumber: '120', gasUsed: String(150_000 + lap), effectiveGasPrice: '1000251' },
        claimKind: 'eth'
      }
    });
    collector.lapEnd({
      userId: 'u0',
      mode: 'headless',
      lapId: `u0:a0:l${lap}`,
      outcome: lap === 2 ? 'LAP_FAILED' : 'LAP_DONE'
    });
  }
  collector.tickSkipped('u1', 'headless', 'claim-proof');
  collector.recordGateBlocked('claim-proof');
  collector.error({
    userId: 'u0',
    mode: 'headless',
    errorClass: 'internal',
    message: 'golden internal error',
    hopId: 'u0:a0:l2:h0'
  });
  collector.error({
    userId: 'u1',
    mode: 'headless',
    errorClass: 'proxy_5xx',
    message: 'HTTP 503',
    endpointClass: 'tracker/activity'
  });
  collector.error({ userId: 'u1', mode: 'headless', errorClass: 'not_ready', message: 'not yet' });
  collector.setSchedulerCounters({
    ticksOffered: 4,
    skippedBackpressure: 1,
    ticksLostToRamp: 0,
    ticksExpected: 4
  });
  advance(5_000);
  collector.resourceSample({
    toolRssMb: 210.5,
    toolCpuPct: 12.25,
    browserProcesses: [],
    eventLoopDelayP99Ms: 4.5
  });
  advance(1_000);
  collector.runEnd({ aborted: false, abortCause: null, lapsInFlightAtStop: 0 });
  const snapshot = collector.snapshot();
  collector.close();
  return { sink, snapshot };
};

const fixedConfig = (): LoadtestConfig => {
  const base = buildTestDevnetConfig();
  return {
    ...base,
    output: { dir: 'loadtest-results/golden', activityLog: true }
  };
};

describe('flag-off golden: pre-S53 artifacts stay byte-identical', () => {
  const config = fixedConfig();
  const { sink, snapshot } = buildScenario();
  const results = buildResultsJson({ snapshot, config });
  const actual = {
    'activity.ndjson': `${sink.lines.join('\n')}\n`,
    'results.json': `${JSON.stringify(results, null, 2)}\n`,
    'summary.md': renderSummaryMd(results, config)
  };

  if (process.env.LOADTEST_UPDATE_GOLDEN === '1') {
    fs.mkdirSync(GOLDEN_DIR, { recursive: true });
    for (const [name, content] of Object.entries(actual)) {
      fs.writeFileSync(
        path.join(GOLDEN_DIR, GOLDEN_FILES[name as keyof typeof GOLDEN_FILES]),
        content
      );
    }
  }

  for (const [name, content] of Object.entries(actual)) {
    it(`${name} matches the golden generated before the S53 changes`, () => {
      const golden = fs.readFileSync(
        path.join(GOLDEN_DIR, GOLDEN_FILES[name as keyof typeof GOLDEN_FILES]),
        'utf8'
      );
      expect(content).toBe(golden);
    });
  }

  it('carries none of the S53-only keys or ndjson kinds', () => {
    const kinds = new Set(sink.lines.map((line) => (JSON.parse(line) as { kind: string }).kind));
    for (const kind of [
      'pump_state',
      'pump_deposit',
      'pump_skipped',
      'wallet_balance',
      'l1_info_leaf',
      'l1_info_poll_error',
      'http_window'
    ]) {
      expect(kinds.has(kind)).toBe(false);
    }
    for (const key of ['pump', 'walletBalances', 'l1InfoTree']) {
      expect(key in results).toBe(false);
    }
  });
});
